-- 037 — Add 50 math questions
--
-- Pure insert, no passage. Ids are deterministic:
-- md5(section || '|' || prompt)::UUID with ON CONFLICT DO NOTHING, so
-- re-running this file is a no-op. Nothing existing is deleted or updated,
-- and user_question_history is never touched.

WITH q(prompt, options, correct_index, difficulty, explanation) AS (VALUES
  ('What is 9 × 12?', '["96", "108", "99", "117"]'::JSONB, 1, 1, 'Break a hard multiplication into easy pieces. Twelve is 10 + 2, so 9 × 12 = 9 × 10 + 9 × 2 = 90 + 18 = 108. If you chose 117, you multiplied by 13 rather than 12, and 96 is 8 × 12. Check by dividing back: 108 ÷ 9 = 12 ✓'),
  ('What is 7² − 3²?', '["16", "49", "40", "58"]'::JSONB, 2, 1, 'Squares do not spread across a subtraction. Work out each square on its own: 7² = 49 and 3² = 9, so 49 − 9 = 40. The value 16 comes from subtracting before squaring, (7 − 3)² = 4², which is a different calculation. The value 49 stops after one square and never subtracts the other.'),
  ('Round 4,682 to the nearest hundred.', '["4,600", "4,700", "4,680", "5,000"]'::JSONB, 1, 1, 'To round to the nearest hundred, look at the digit immediately to the right of the hundreds place. That tens digit is 8, which is 5 or more, so the hundreds digit climbs from 6 to 7 and everything after it becomes zero: 4,700. Rounding to the nearest ten instead gives 4,680, and 5,000 is the nearest thousand.'),
  ('What is 0.4 × 0.2?', '["0.6", "0.8", "0.08", "8"]'::JSONB, 2, 1, 'Multiply as though the decimal points were not there, then put them back. 4 × 2 = 8, and each factor has one decimal place, so the product needs two: 0.08. The value 0.6 comes from adding the numbers, and 0.8 uses only one decimal place. Multiplying by an amount under 1 makes the result smaller.'),
  ('Which of these numbers is prime?', '["29", "21", "27", "33"]'::JSONB, 0, 1, 'A prime number has exactly two factors, 1 and itself. Test small divisors on the others: 21 = 3 × 7, 27 = 3 × 9, and 33 = 3 × 11, so each one breaks apart. Nothing from 2 through 5 divides 29, and 6 × 6 already passes 29, so 29 is prime. Being odd does not make a number prime.'),
  ('What is 3/5 expressed as a percent?', '["30%", "35%", "53%", "60%"]'::JSONB, 3, 1, 'A fraction turns into a percent in two steps: divide, then multiply by 100. Here 3 ÷ 5 = 0.6, and 0.6 × 100 = 60%. The value 35% only reuses the digits 3 and 5, and 53% swaps them around. Sanity check: 3/5 is more than half, and 60% is the one choice above 50%.'),
  ('What is the value of 4a + 3 when a = 6?', '["27", "13", "24", "42"]'::JSONB, 0, 1, 'Substitute the value, then follow order of operations, multiplying before adding: 4(6) + 3 = 24 + 3 = 27. The value 42 comes from adding 4 + 3 and then multiplying 7 × 6, but the 3 is not attached to the a. The value 13 comes from adding 4 + 3 + 6 instead of multiplying at all.'),
  ('What is −7 + 12?', '["−19", "5", "−5", "19"]'::JSONB, 1, 1, 'Adding a positive number moves you to the right on the number line. Start at −7 and step 12 to the right: seven steps reach 0, and the remaining five land on 5. The value −19 comes from adding 7 and 12 while keeping the minus sign, and −5 has the right size with the wrong sign attached.'),
  ('What is 6 − (−4)?', '["−10", "−2", "10", "2"]'::JSONB, 2, 1, 'Subtracting a negative is the same as adding a positive, the way taking away a debt leaves you better off: 6 − (−4) = 6 + 4 = 10. The value 2 comes from reading the problem as 6 − 4, and −10 keeps a minus sign that the two negatives have already cancelled out.'),
  ('What is 1/3 of 21?', '["3", "18", "7", "63"]'::JSONB, 2, 1, 'In math wording, ''of'' means multiply. One third of 21 is (1/3) × 21 = 21 ÷ 3 = 7. The value 63 comes from multiplying by 3 rather than dividing, which makes the amount grow when it should shrink, and 18 comes from subtracting 3. A third of a number has to be much smaller than the whole.'),
  ('What is the perimeter of a rectangle with length 15 cm and width 9 cm?', '["24 cm", "60 cm", "135 cm", "48 cm"]'::JSONB, 3, 1, 'Perimeter is the distance all the way around, so every side gets counted. Two lengths and two widths: 2(15) + 2(9) = 30 + 18 = 48 cm. The value 24 cm counts each side only once, and 135 is the area, 15 × 9, which measures the space inside rather than the fence around the outside.'),
  ('What is the area of a square with side length 7?', '["14", "28", "42", "49"]'::JSONB, 3, 1, 'Area covers the inside of a shape, so you multiply two lengths: 7 × 7 = 49 square units. The value 28 is the perimeter, 4 × 7, the distance around the outside, and 14 adds only two sides. Picture a 7 by 7 grid of little squares and count them: 49 ✓'),
  ('How many minutes are in 3.5 hours?', '["195", "300", "210", "350"]'::JSONB, 2, 1, 'Changing to a smaller unit means multiplying, since minutes come in bigger counts than hours. 3.5 × 60 is 3 × 60 = 180 plus half an hour, 30, giving 210 minutes. The value 195 treats the .5 as 15 minutes rather than 30, and 350 comes from multiplying by 100 instead of 60.'),
  ('What is 25% of 60?', '["15", "12", "20", "24"]'::JSONB, 0, 1, 'Percent means per hundred, and 25% is another name for 1/4. One quarter of 60 is 60 ÷ 4 = 15. The value 24 is 40% of 60, and 20 is a third rather than a quarter. Check the answer by rebuilding the whole: four groups of 15 give 60 ✓'),
  ('Find the median of: 8, 3, 12, 5, 10.', '["8", "5", "7.6", "12"]'::JSONB, 0, 1, 'The median is the middle value once the numbers are lined up in order, which is not the same as an average. Sorted, the list reads 3, 5, 8, 10, 12, and with five numbers the middle one is 8. The value 7.6 is the mean, found by adding and dividing, and 12 is only the largest value in the list.'),
  ('What is 7/8 expressed as a decimal?', '["0.78", "0.87", "1.142", "0.875"]'::JSONB, 3, 1, 'A fraction is a division waiting to happen: 7 ÷ 8. Carrying that division out gives 0.875 exactly, with no rounding needed, so it does not stop at 0.87. The value 0.78 swaps the digits, and 1.142 comes from dividing 8 by 7, but 7/8 is less than one whole, so its decimal has to start with 0.'),
  ('What is the value of 3 × (8 − 5)²?', '["9", "27", "54", "81"]'::JSONB, 1, 1, 'Order of operations: parentheses, then exponents, then multiplication. Inside the parentheses, 8 − 5 = 3; then 3² = 9; then 3 × 9 = 27. The value 81 comes from multiplying 3 × 3 before squaring, which turns the problem into 9². The value 9 is (8 − 5)² on its own, stopping before the outside 3 is used.'),
  ('Which fraction is equivalent to 3/4?', '["9/12", "4/3", "6/9", "12/15"]'::JSONB, 0, 1, 'Equivalent fractions come from multiplying the top and the bottom by the same number. Multiply 3/4 by 3/3 and you get 9/12, the same value written differently. The others do not match: 6/9 reduces to 2/3, 12/15 reduces to 4/5, and 4/3 is 3/4 flipped upside down, a number greater than 1.'),
  ('What is 10² ÷ 5?', '["4", "20", "50", "100"]'::JSONB, 1, 1, 'Exponents come before division. Square first, 10² = 100, then divide: 100 ÷ 5 = 20. The value 4 comes from dividing before squaring, 10 ÷ 5 = 2 and then 2², which changes the problem. The value 100 stops after the exponent, and 50 halves 100 instead of taking a fifth of it.'),
  ('Which of these values is the greatest: 2/3, 0.6, 5/8, or 0.58?', '["0.6", "5/8", "0.58", "2/3"]'::JSONB, 3, 1, 'Put every number in the same form and the comparison becomes easy. As decimals: 2/3 = 0.667, 0.6 = 0.600, 5/8 = 0.625, and 0.58. Lined up that way, 2/3 is the largest. The value 5/8 tempts people because eighths look precise and small, but 0.625 still falls short of 0.667.'),
  ('What is the sum of the interior angles of a quadrilateral?', '["180°", "270°", "540°", "360°"]'::JSONB, 3, 1, 'Any four-sided figure can be cut into two triangles by drawing one diagonal, and every triangle holds 180°. Two triangles give 2 × 180 = 360°. The value 180° covers one triangle only, and 540° is the sum for a five-sided figure. A rectangle confirms it: four right angles make 4 × 90 = 360° ✓'),
  ('How many inches are in 4 feet?', '["36", "48", "40", "52"]'::JSONB, 1, 1, 'There are 12 inches in one foot, so going from feet to inches means multiplying: 4 × 12 = 48. The value 36 is only 3 feet, and 40 comes from multiplying by 10 rather than 12. Sanity check: 48 inches is about the height of a young child, which is a reasonable four feet.'),
  ('What is 1/4 + 1/3?', '["1/7", "2/7", "5/12", "7/12"]'::JSONB, 3, 1, 'Fractions can only be added when the pieces are the same size, so find a common denominator first. Twelfths work: 1/4 = 3/12 and 1/3 = 4/12, so the sum is 7/12. The value 2/7 comes from adding tops and bottoms separately, which would make the total smaller than either fraction you started with.'),
  ('A recipe uses 3 eggs to make 12 pancakes. At the same rate, how many eggs are needed for 20 pancakes?', '["5", "4", "6", "8"]'::JSONB, 0, 2, 'Find the unit rate, then scale it up. Three eggs make 12 pancakes, so one egg makes 4 pancakes, and 20 ÷ 4 = 5 eggs. The value 8 comes from subtracting 12 from 20 and stopping there, which ignores the rate entirely. Check: 5 eggs at 4 pancakes each gives 20 pancakes ✓'),
  ('Solve for x: (x − 3)/2 = 6', '["9", "12", "18", "15"]'::JSONB, 3, 2, 'Undo the operations in reverse order. The final operation applied to x was the division, so clear that first: multiply both sides by 2 to get x − 3 = 12. Then add 3, giving x = 15. The value 9 comes from adding 3 to 6 before multiplying. Check: (15 − 3)/2 = 12/2 = 6 ✓'),
  ('What is 2/5 ÷ 3/10?', '["3/25", "4/3", "3/4", "12/25"]'::JSONB, 1, 2, 'Dividing by a fraction means multiplying by its reciprocal, so flip the second fraction over: (2/5) × (10/3) = 20/15 = 4/3. The value 3/25 comes from multiplying straight across without flipping. Dividing by an amount under 1 makes the result grow, and 4/3 is indeed larger than the 2/5 you began with.'),
  ('On a map, 1 inch represents 25 miles. Two cities are 3.5 inches apart on the map. How far apart are they?', '["70 miles", "75 miles", "87.5 miles", "105 miles"]'::JSONB, 2, 2, 'A scale is a rate: each inch on the map stands for 25 real miles, so multiply. 3.5 × 25 = 75 + 12.5 = 87.5 miles. The value 75 uses only 3 inches and drops the half inch, and 70 miles would be correct if the scale were 20 miles per inch. The value 105 miles uses a scale of 30.'),
  ('After a 25% discount, a jacket costs $60. What was the original price?', '["$80", "$45", "$75", "$85"]'::JSONB, 0, 2, 'After a 25% discount you still pay 75% of the original, so $60 is 0.75 of the price you want: 60 ÷ 0.75 = $80. The value $75 comes from adding 25% onto $60, but the discount was taken off the larger original price, not off the sale price. Check: 25% of 80 is 20, and 80 − 20 = 60 ✓'),
  ('What is the slope of the line passing through (2, 3) and (6, 11)?', '["1/2", "4", "8", "2"]'::JSONB, 3, 2, 'Slope is rise over run: the change in y divided by the change in x. Here y climbs from 3 to 11, a rise of 8, while x goes from 2 to 6, a run of 4, so the slope is 8/4 = 2. The value 1/2 flips the fraction upside down, and 8 uses the rise alone without dividing.'),
  ('The area of a circle is 49π square units. What is its circumference, in terms of π?', '["7π", "14π", "24.5π", "98π"]'::JSONB, 1, 2, 'Use the area to find the radius, then move to circumference. πr² = 49π means r² = 49, so r = 7, and the circumference is 2πr = 14π. The value 7π leaves out the 2 in 2πr, and 98π comes from doubling the area rather than working from the radius.'),
  ('A rhombus has diagonals of length 6 and 8. What is its area?', '["14", "28", "24", "48"]'::JSONB, 2, 2, 'The area of a rhombus is half the product of its diagonals, because the diagonals cut it into four right triangles: (6 × 8)/2 = 24. The value 48 multiplies the diagonals but forgets the halving, and it is really the area of the rectangle drawn around the rhombus. The value 14 adds the diagonals instead.'),
  ('What is the value of (2/3)²?', '["2/9", "4/9", "4/3", "8/27"]'::JSONB, 1, 2, 'Squaring a fraction squares the top and the bottom, since (2/3)² means (2/3) × (2/3) = (2 × 2)/(3 × 3) = 4/9. The value 2/9 squares only the denominator and 4/3 squares only the numerator. Check with decimals: 2/3 is about 0.67, and 0.67 × 0.67 is about 0.44, matching 4/9 ✓'),
  ('What is 15% of 240?', '["16", "24", "40", "36"]'::JSONB, 3, 2, 'Break an awkward percent into friendly pieces. 10% of 240 is 24, and 5% is half of that, 12, so 15% is 24 + 12 = 36. The value 24 stops at 10%, and 16 comes from dividing by 15 rather than taking 15 percent. Sanity check: 36 is a little more than a tenth of 240, as it should be.'),
  ('Three-fifths of a number is 24. What is the number?', '["14.4", "30", "40", "48"]'::JSONB, 2, 2, 'When a fraction of an unknown number is given, divide by that fraction to get back to the whole: 24 ÷ (3/5) = 24 × 5/3 = 40. The value 14.4 comes from taking 3/5 of 24 instead, shrinking a number that should grow. Check: three fifths of 40 is 3 × 8 = 24 ✓'),
  ('A box contains 5 red, 3 blue, and 4 green marbles. One is drawn at random. What is the probability that it is NOT blue?', '["1/4", "1/3", "3/4", "2/3"]'::JSONB, 2, 2, 'For a NOT question, count the outcomes you do want. There are 5 + 3 + 4 = 12 marbles and 9 of them are not blue, so the probability is 9/12 = 3/4. The value 1/4 is the chance the marble IS blue, 3/12. The two chances have to add to one whole, and 1/4 + 3/4 = 1 ✓'),
  ('In the proportion 3/8 = x/40, what is x?', '["15", "5", "12", "24"]'::JSONB, 0, 2, 'In a proportion, whatever you do to the bottom you must also do to the top. The denominator went from 8 to 40, which is times 5, so the numerator does the same: x = 3 × 5 = 15. The value 5 is only the scale factor, and 24 comes from multiplying 3 by 8 rather than by 5.'),
  ('When a number is increased by 12, the result is three times the number. What is the number?', '["6", "3", "4", "9"]'::JSONB, 0, 2, 'Turn the words into an equation: n + 12 = 3n. Take n from both sides and 12 = 2n, so n = 6. The value 4 comes from dropping that step and solving 12 = 3n, and 3 comes from dividing 12 by 4. Check: 6 + 12 = 18, and three times 6 is also 18 ✓'),
  ('The average of four numbers is 15. Three of the numbers are 12, 18, and 20. What is the fourth number?', '["8", "10", "13", "25"]'::JSONB, 1, 2, 'An average tells you the total: four numbers averaging 15 must add to 4 × 15 = 60. The three given numbers add to 12 + 18 + 20 = 50, so the missing one is 60 − 50 = 10. Test 13 and you get a total of 63, an average of 15.75, which is too high, so 13 cannot be the fourth number.'),
  ('How many 3-inch pieces can be cut from a ribbon that is 4 feet long?', '["12", "14", "16", "48"]'::JSONB, 2, 2, 'Match the units before dividing. Four feet is 4 × 12 = 48 inches, and 48 ÷ 3 = 16 pieces. The value 48 is the ribbon''s length in inches, not a count of pieces, and 12 is what you get from a 36-inch ribbon. Check: 16 pieces at 3 inches each use up 48 inches ✓'),
  ('Two vertical angles measure 3x degrees and 75 degrees. What is the value of x?', '["15", "35", "45", "25"]'::JSONB, 3, 2, 'Vertical angles are the pair sitting opposite each other where two lines cross, and they are always equal, not supplementary. So 3x = 75 and x = 25. The value 35 comes from treating them as a straight-line pair, using 180 − 75 = 105 and dividing by 3. Check: 3 × 25 = 75 ✓'),
  ('If x + 1/x = 5, what is the value of x² + 1/x²?', '["10", "25", "23", "27"]'::JSONB, 2, 3, 'Square the whole equation and see what turns up. (x + 1/x)² = x² + 2 + 1/x², and that equals 5² = 25, so x² + 1/x² = 25 − 2 = 23. The value 25 forgets to remove the middle term of 2, and 10 comes from doubling 5, as if squaring meant multiplying by two.'),
  ('What is the units digit of 7 raised to the 25th power?', '["1", "7", "3", "9"]'::JSONB, 1, 3, 'Powers of 7 cycle through their final digits: 7, 9, 3, 1, then start over, a pattern four long. Divide the exponent by 4 and look at what is left over: 25 is 24 + 1, so the 25th power ends the same way the 1st does, in a 7. The value 1 fits exponents that divide evenly by 4, such as 24.'),
  ('A 6-liter mixture is 1/3 alcohol. How many liters of water must be added so that the mixture is 1/4 alcohol?', '["2", "1", "1.5", "3"]'::JSONB, 0, 3, 'Adding water changes the total but leaves the alcohol alone, so pin down the fixed part: 1/3 of 6 is 2 liters of alcohol. You want those 2 liters to be 1/4 of the new total, so the new total must be 8 liters, meaning 8 − 6 = 2 liters of water. The value 1.5 comes from changing the alcohol amount too.'),
  ('What are the solutions of x² − 5x − 14 = 0?', '["x = −7 and x = 2", "x = 2 and x = 7", "x = −2 and x = 7", "x = −7 and x = −2"]'::JSONB, 2, 3, 'Factor by hunting for two numbers that multiply to −14 and add to −5: those are −7 and +2, so (x − 7)(x + 2) = 0. A factor hits zero when x is the opposite of the number inside it, giving x = 7 and x = −2. The pair x = −7 and x = 2 skips that sign flip. Check: 7 × (−2) = −14 ✓'),
  ('The length of a rectangle is increased by 20% and its width is decreased by 20%. What happens to the area?', '["It decreases by 4%", "It stays the same", "It increases by 4%", "It decreases by 20%"]'::JSONB, 0, 3, 'Percent changes multiply, so they do not cancel out. The new area is 1.2 × 0.8 = 0.96 of the old one, a 4% decrease. It feels as if the area stays the same, but the 20% loss is taken from a width that is then paired with an already-stretched length. Try a 10 by 10 square: 12 × 8 = 96, not 100.'),
  ('The interior angles of a regular polygon sum to 1080°. How many sides does the polygon have?', '["8", "6", "7", "10"]'::JSONB, 0, 3, 'A polygon with n sides splits into n − 2 triangles, so its angles total (n − 2) × 180°. Set (n − 2) × 180 = 1080 and divide: n − 2 = 6, so n = 8. The value 6 stops at that division and never adds the 2 back, and 10 comes from dividing 1080 by 108 instead of 180.'),
  ('What is the measure of the smaller angle formed by the hands of a clock at 3:30?', '["15°", "90°", "105°", "75°"]'::JSONB, 3, 3, 'The hour hand keeps drifting between the numbers, which is the whole trick here. At 3:30 the minute hand sits on the 6, at 180°, while the hour hand has moved halfway from 3 to 4, from 90° to 105°. The gap is 180 − 105 = 75°. The value 90° treats the hour hand as still parked on the 3.'),
  ('Ann can finish a job alone in 12 days and Ben can finish the same job alone in 18 days. They work together for 4 days, then Ann leaves. How many more days does Ben need?', '["6", "8", "7", "9"]'::JSONB, 1, 3, 'Work problems run on rates, not on times. Together they finish 1/12 + 1/18 = 3/36 + 2/36 = 5/36 of the job each day, so 4 days covers 20/36. That leaves 16/36, and Ben works at 1/18 = 2/36 a day, so he needs 16 ÷ 2 = 8 more days. The value 9 assumes half the job is left, but slightly less than half remains.'),
  ('A square garden has an area of 144 square feet. A path 2 feet wide surrounds the garden on all sides. What is the area of the path alone?', '["112 square feet", "56 square feet", "96 square feet", "256 square feet"]'::JSONB, 0, 3, 'Find both squares, then subtract. An area of 144 means the garden is 12 by 12. A 2-foot path on every side adds 2 twice to each dimension, so the outer square is 16 by 16 = 256, and the path alone is 256 − 144 = 112 square feet. The value 96 counts four 12-by-2 strips and misses the four corner squares.'),
  ('In a class, 18 students play soccer, 15 play basketball, 7 play both sports, and 5 play neither. How many students are in the class?', '["26", "31", "33", "38"]'::JSONB, 1, 3, 'Adding 18 and 15 counts the 7 two-sport students twice, so subtract them once: 18 + 15 − 7 = 26 students play at least one sport. Then add the 5 who play neither, giving 31. The value 26 stops before those 5 are included, and 38 adds 18 + 15 + 5 without ever removing the double count.')
)
INSERT INTO questions (id, section, passage, prompt, options, correct_index, difficulty, explanation)
SELECT md5('math' || '|' || q.prompt)::UUID, 'math'::section_type, NULL,
       q.prompt, q.options, q.correct_index, q.difficulty, q.explanation
FROM q
ON CONFLICT (id) DO NOTHING;

-- ── Verification: expect 50 rows ─────────────────────────────────────
SELECT '037 math' AS migration, COUNT(*)::TEXT AS present, '50' AS expected
FROM questions
WHERE id IN (
  md5('math' || '|' || 'What is 9 × 12?')::UUID,
  md5('math' || '|' || 'What is 7² − 3²?')::UUID,
